        function GetInt(): integer;
        begin
          p := Pos(',', sProfile);
          if p = 0 then begin
            substr := sProfile;
            sProfile := '';
          end else begin
            substr := copy(sProfile, 1, p-1);
            Delete(sProfile, 1, p);
          end;
          Result := StrToInt(Trim(substr));
        end;

        procedure PrepareSticker(sProfile, ScaleX, ScaleY);
        begin
          VarRemove('STx');
          VarRemove('STz');
          sCount := 0;
          ProfileSizeX := GetInt;
          ProfileSizeY := GetInt;
          while Length(sProfile) > 0 do begin
            STx[sCount] := (GetInt / ProfileSizeX * 2 - 1) * ScaleX;
            STz[sCount] := (GetInt / ProfileSizeY * 2 - 1) * ScaleY;
            Inc(sCount);
          end;
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
        end;


        // Tenon/groove

        procedure AddTenon(x, y, z, nx, ny, nz);
        begin
          PartNo := CallGlobal('GetVisiblePartContaining', x, y, z);
          FaceNo := CallGlobal('FindFaceByNorm', PartNo, nx, ny, nz);
          CallGlobal('SetTenon', 1, PartNo, FaceNo);
          if VarExists('ShowTextures') then
            if ShowTextures then
              CallGlobal('SetTexture', 'Tenon', PartNo, FaceNo, 0);
        end;

        procedure AddGroove(x, y, z, nx, ny, nz);
        begin
          PartNo := CallGlobal('GetVisiblePartContaining', x, y, z);
          FaceNo := CallGlobal('FindFaceByNorm', PartNo, nx, ny, nz);
          CallGlobal('SetGroove', 1, PartNo, FaceNo);
          if VarExists('ShowTextures') then
            if ShowTextures then
              CallGlobal('SetTexture', 'Groove', PartNo, FaceNo, 0);
        end;
    

        
            
